@startuml

class Bookmaker {
  + name : string
  + acceptBet(Bet: Bet) : void
  + calculateTotalWinnings() : double
  + calculateTotalLosses() : double
}

class Bettor {
  + name : string
  + id : int
}

class Race {
  + raceId : int
  + date : date
}

class Runner {
  + name : string
}

class Horse {
  + breed : string
  + age : int
}

class Jockey {
  + name : string
}

class Bet {
  + amount : double
  + odds : double
}

Bettor "1" -- "*" Bet
Race "1" -- "1..*" Runner
Runner --|> Runner
Horse --|> Runner
Jockey "1" -- "1" Horse
Bet "*" -- "1" Race
Bet "*" -- "1" Runner
Bookmaker "1" -- "*" Bet
Bookmaker "1" -- "*" Bettor

@enduml

